      mask = "memory",
      music = "25_Romantic_Quiet_MAS",
      renwu = "npc",
      role1 = 198000,
      role2 = 102102,
      role3 = 102201,
      role5 = 198402,
      sentence = "Tiny flowers blossomed and faded. They accompanied a person for a lifetime, then returned to stillness.",
      next = {30}
    },
    [30] = {
      beijing = 4224,
      dialog = 3,
      mask = "memory",
      music = "25_Romantic_Quiet_MAS",
      renwu = "npc",
      role1 = 198000,
      role2 = 102102,
      role3 = 102201,
      role5 = 198402,
      sentence = "This was a perishing world. Victor had watched over it throughout, witnessing the fading away of time and love.",
      next = {31}
    },
    [31] = {
      beijing = 4224,
      dhead = 111,
      dialog = 1,
      mask = "memory",
      music = "25_Romantic_Quiet_MAS",
      renming = "$u",
      renwu = "npc",
      role1 = 198000,
      role2 = 102102,
      role3 = 102201,
      role5 = 198402,
      sentence = "Why do you choose to guard over the underworld?",
