    },
    [33] = {
      beijing = 4224,
      dialog = 2,
      idx = 1,
      male = 1,
      mask = "memory",
      music = "25_Romantic_Quiet_MAS",
      renming = "Victor",
      renwu = "npc",
      role1 = 198000,
      role2 = 102101,
      role3 = 102201,
      role5 = 198402,
      sentence = "There is no difference between life and death.",
      voice = 2,
      next = {34}
    },
    [34] = {
      beijing = 4224,
