      renwu = "npc",
      role1 = 198000,
      role2 = 102102,
      role3 = 102201,
      role5 = 198402,
      sentence = "As I looked into Victor's ever-tranquil gaze, I remembered his profile as he sat by the marketplace. I couldn't see a bit of complaint or fatigue.",
