      mask = "memory",
      music = "25_Romantic_Quiet_MAS",
      renwu = "npc",
      role1 = 198000,
      role2 = 102102,
      role3 = 102201,
      role5 = 198402,
      sentence = "He was just calmly paused outside of time. It seemed that all life would pass by him, then disappear.",
