    [56] = {
      beijing = 4224,
      dialog = 3,
      music = "25_Romantic_Quiet_MAS",
      renwu = "npc",
      sentence = "Upon becoming aware that I sincerely wanted to learn about the underworld, and about him, Victor also began to earnestly cooperate with me in my work.",
