    },
    [59] = {
      beijing = 4224,
      dialog = 3,
      music = "25_Romantic_Quiet_MAS",
      renwu = "npc",
      sentence = "Hearing that familiar voice suddenly, I froze for a moment and realized that I'd walked near that hillside without even realizing it.",
