      renwu = "npc",
      role1 = 197000,
      role2 = 101103,
      role3 = 101201,
      ruchang = -1,
      sentence = "His brow furrowed slightly, as if he was still mad about what had happened just now. I subconsciously shrunk back a bit.",
      next = {61}
    },
    [61] = {
      beijing = 4224,
      dhead = 105,
