    },
    [65] = {
      beijing = 4224,
      dialog = 3,
      music = "102_LiZeyan_MMO",
      renwu = "npc",
      sentence = "In that tranquil word, partings and witherings played out silently before our eyes.",
      next = {66}
    },
    [66] = {
      beijing = 4224,
      dialog = 3,
      music = "102_LiZeyan_MMO",
      renwu = "npc",
      sentence = "As I watched those departed souls, I suddenly thought that if I became human, after death I would be stripped of all my memories too.",
