    },
    [67] = {
      beijing = 4224,
      dialog = 3,
      music = "102_LiZeyan_MMO",
      renwu = "npc",
      sentence = "When my soul walked through the gates of the underworld, no matter if I had lived my whole life as a human, or as a god of love, wouldn't all that time just vanish?",
