      renwu = "npc",
      role1 = 198000,
      role2 = 102102,
      role3 = 102201,
      role5 = 198402,
      sentence = "The exuberant flowers blossomed with abandon, incredibly intense, yet tender, like a world-embracing love that in its final moment was embracing this one.",
      next = {72}
    },
    [72] = {
      beijing = 4224,
