      dialog = 3,
      music = "102_LiZeyan_MMO",
      renwu = "npc",
      role1 = 198000,
      role2 = 102101,
      role3 = 102201,
      role5 = 198402,
      sentence = "\"Forever\" was a blessing, but could also become a curse. It can guard over lovers, and also become a shackle.",
      next = {111}
    },
    [81] = {
      beijing = 4224,
      dialog = 3,
      music = "102_LiZeyan_MMO",
      renwu = "npc",
      sentence = "I looked at those fading fragments for a long while, then finally squatted down and picked up my bow and arrow.",
