    },
    [83] = {
      beijing = 4224,
      dialog = 3,
      music = "102_LiZeyan_MMO",
      renwu = "npc",
      sentence = "Holding my bow and arrow, I looked at those flowers and, one stroke at a time, I carved out a similar shape on the ground.",
