      renwu = "npc",
      role1 = 3122000,
      role2 = 302108,
      role3 = 302203,
      sentence = "Captain, people out there all say we're the free and unvanquished [i]Morning Star[/i], but do any of them know that the [i]Morning Star[/i] never stops because it doesn't have an anchor!?",
